INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, vertical, ordem, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum)
VALUES
('projetos.clientes.kpi.total','/dashboard/projetos/clientes','Indicadores','hub_projetos',20,'Clientes ativos','Indicador calculado, não se preenche. Conta os clientes ativos da empresa selecionada.','Mostra o tamanho da carteira de clientes de obra.','4','Procurar aqui cliente excluído: ele foi arquivado e sai da contagem.'),
('projetos.clientes.kpi.com_obra','/dashboard/projetos/clientes','Indicadores','hub_projetos',21,'Clientes com obra','Indicador calculado. Conta os clientes que têm pelo menos uma obra cadastrada.','Mostra quantos clientes já viraram obra; os outros ainda estão na fase comercial.','2 de 4','Criar a obra sem escolher o cliente e ela não contar aqui.'),
('projetos.clientes.kpi.incompletos','/dashboard/projetos/clientes','Indicadores','hub_projetos',22,'Cadastro incompleto','Indicador calculado. Conta os clientes sem CPF/CNPJ ou sem telefone e e-mail.','Sem documento a proposta e a nota não saem certas; sem contato a equipe não consegue agendar visita.','1','Deixar para completar depois e travar a proposta na hora de enviar.'),
('projetos.clientes.filtro_tipo','/dashboard/projetos/clientes','Filtros','hub_projetos',23,'Filtro por tipo de pessoa','Escolha Todos, Pessoa jurídica (CNPJ) ou Pessoa física (CPF).','Separa empresas de pessoas físicas, que têm documentos e contratos diferentes.','Pessoa física','Esquecer o filtro ligado e achar que o cliente sumiu.'),
('projetos.clientes.filtro_cidade','/dashboard/projetos/clientes','Filtros','hub_projetos',24,'Filtro por cidade','Escolha a cidade do cadastro do cliente. A lista só traz cidades que já têm cliente.','Ajuda a montar a rota de visitas e a ver a carteira por região.','Chapecó','Cidade digitada de jeitos diferentes no cadastro aparece duas vezes: padronize ao editar.'),
('projetos.clientes.lista','/dashboard/projetos/clientes','Lista','hub_projetos',25,'Lista de clientes','Toque no cliente para abrir o endereço, as obras dele e as ações.','Cada linha mostra tipo, documento, cidade, contato e quantas obras o cliente tem.','Clínica Bem Viver · 1 obra','Cliente em vermelho "sem telefone nem e-mail": complete em Editar antes de agendar visita.'),
('projetos.clientes.obras','/dashboard/projetos/clientes','Lista','hub_projetos',26,'Obras deste cliente','Lista calculada das obras ligadas ao cliente. Toque na obra para abrir o painel dela.','É o elo Cliente → Obra → Orçamento: o custo e o resultado de cada obra ficam no painel da obra.','Reforma da recepção · em andamento','Cadastrar a mesma obra duas vezes para o mesmo cliente.'),
('projetos.clientes.tipo_pessoa','/dashboard/projetos/clientes','Cadastro','hub_projetos',27,'Tipo de pessoa','Escolha Pessoa jurídica para empresa (CNPJ) ou Pessoa física (CPF).','Define o documento pedido e como o cliente sai na proposta, no contrato e na nota.','Pessoa jurídica','Cadastrar empresa como pessoa física e a nota sair com CPF.'),
('projetos.clientes.acao.novo','/dashboard/projetos/clientes','Ações','hub_projetos',28,'Novo cliente','Abre o cadastro para incluir um cliente de obra. Só o nome é obrigatório.','O cliente vira o dono da obra, que ancora o orçamento e a proposta.','Residencial Vista Verde','Cadastrar de novo um cliente que já existe: busque antes.'),
('projetos.clientes.acao.editar','/dashboard/projetos/clientes','Ações','hub_projetos',29,'Editar cliente','Abre o cadastro do cliente para corrigir documento, contato ou endereço.','Mantém os dados certos na proposta, no contrato e na nota.','Incluir o CNPJ que faltava','Trocar o nome de um cliente por outro em vez de cadastrar um novo.'),
('projetos.clientes.acao.nova_obra','/dashboard/projetos/clientes','Ações','hub_projetos',30,'Nova obra','Informe o nome da obra; ela nasce em rascunho, já ligada a este cliente.','Começa a obra do cliente para orçar, planejar e acompanhar custo e resultado.','Ampliação do galpão','Criar a obra fora do cliente e perder o vínculo.'),
('projetos.clientes.acao.oportunidade','/dashboard/projetos/clientes','Ações','hub_projetos',31,'Nova oportunidade','Abre o funil de oportunidades para registrar o pedido de orçamento deste cliente.','Guarda o histórico da negociação antes de virar proposta e obra.','Cliente pediu reforma da fachada','Ir direto para a obra e perder o funil comercial.'),
('projetos.clientes.acao.excluir','/dashboard/projetos/clientes','Ações','hub_projetos',32,'Excluir cliente','Pede confirmação e arquiva o cliente: ele sai da lista, mas obras e histórico ficam guardados.','Limpa a lista sem apagar nada do que já foi feito com o cliente.','Cliente cadastrado em duplicidade','Excluir achando que apaga as obras: elas continuam no Hub.')
